-- Phase 52 Migration
CREATE TABLE IF NOT EXISTS enterprise_assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, tenant_id UUID, asset_tag TEXT NOT NULL, asset_name TEXT NOT NULL, asset_category TEXT DEFAULT 'PRODUCTION_EQUIPMENT', manufacturer TEXT NOT NULL, model_number TEXT NOT NULL, serial_number TEXT NOT NULL, operational_status TEXT DEFAULT 'OPERATIONAL', criticality TEXT DEFAULT 'BUSINESS_CRITICAL', replacement_value_usd NUMERIC(14,2) DEFAULT 450000.00, expected_useful_life_years INTEGER DEFAULT 10, provenance_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_types (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, type_code TEXT NOT NULL, type_name TEXT NOT NULL, standard_maintenance_interval_days INTEGER DEFAULT 90, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_facilities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, facility_name TEXT NOT NULL, facility_type TEXT DEFAULT 'MANUFACTURING_PLANT', region TEXT DEFAULT 'NORTH_AMERICA', total_area_sqft NUMERIC(10,2) DEFAULT 120000.00, capacity_utilization_pct NUMERIC(5,2) DEFAULT 78.5, status TEXT DEFAULT 'OPERATIONAL', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_facility_zones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, facility_id UUID, zone_name TEXT NOT NULL, zone_type TEXT DEFAULT 'CLEAN_ROOM', max_occupancy INTEGER DEFAULT 45, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_locations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, facility_id UUID, zone_id UUID, assigned_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_lifecycle (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, lifecycle_stage TEXT DEFAULT 'OPERATIONAL', remaining_useful_life_years NUMERIC(5,2) DEFAULT 6.5, total_cost_of_ownership_usd NUMERIC(14,2) DEFAULT 520000.00, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_conditions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, condition_score NUMERIC(5,2) DEFAULT 88.5, degradation_rate_pct NUMERIC(5,2) DEFAULT 1.2, observation_type TEXT DEFAULT 'INSPECTION_DERIVED', assessed_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_utilization (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, operating_hours NUMERIC(8,2) DEFAULT 1840.0, idle_hours NUMERIC(8,2) DEFAULT 320.0, utilization_rate NUMERIC(5,2) DEFAULT 85.2, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_availability (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, availability_pct NUMERIC(5,2) DEFAULT 99.4, mtbf_hours NUMERIC(8,2) DEFAULT 720.0, mttr_hours NUMERIC(6,2) DEFAULT 4.2, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_maintenance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, maintenance_type TEXT DEFAULT 'PREVENTIVE', scheduled_date DATE NOT NULL, completed_date DATE, status TEXT DEFAULT 'COMPLETED', maintenance_cost_usd NUMERIC(10,2) DEFAULT 4500.00, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_maintenance_backlog (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, task_title TEXT NOT NULL, priority TEXT DEFAULT 'HIGH', estimated_hours NUMERIC(6,2) DEFAULT 12.0, is_overdue BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_inspections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, inspection_type TEXT DEFAULT 'STATUTORY_SAFETY', passed BOOLEAN DEFAULT true, findings TEXT DEFAULT 'Compliant with safety regulations', inspected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_failures (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, failure_mode TEXT NOT NULL, root_cause TEXT DEFAULT 'BEARING_WEAR', severity TEXT DEFAULT 'HIGH', occurred_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_downtime (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, downtime_hours NUMERIC(6,2) DEFAULT 8.5, downtime_type TEXT DEFAULT 'UNPLANNED', financial_impact_usd NUMERIC(12,2) DEFAULT 35000.00, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_dependencies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, parent_asset_id UUID, child_asset_id UUID, dependency_type TEXT DEFAULT 'PHYSICAL_POWER', criticality TEXT DEFAULT 'CRITICAL', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_single_points (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, exposure_level TEXT DEFAULT 'HIGH_EXPOSURE', mitigation_plan TEXT DEFAULT 'Procure standby redundant unit', evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_spare_parts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, part_number TEXT NOT NULL, part_name TEXT NOT NULL, quantity_on_hand INTEGER DEFAULT 8, reorder_point INTEGER DEFAULT 3, lead_time_days INTEGER DEFAULT 14, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_vendor_dependencies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, vendor_name TEXT NOT NULL, service_contract_id TEXT DEFAULT 'SC-8821', sla_response_hours INTEGER DEFAULT 4, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_lifecycle_costs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, projected_tco_usd NUMERIC(14,2) NOT NULL, realized_tco_usd NUMERIC(14,2) DEFAULT 0.00, variance_usd NUMERIC(14,2) DEFAULT 0.00, calculated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_forecasts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, forecast_horizon TEXT DEFAULT '12_MONTHS', projected_replacement_cost_usd NUMERIC(14,2) DEFAULT 1250000.00, projected_downtime_hours NUMERIC(8,2) DEFAULT 42.0, status TEXT DEFAULT 'FORECAST', confidence_score NUMERIC(5,2) DEFAULT 88.0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_scenarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, scenario_name TEXT NOT NULL, scenario_type TEXT DEFAULT 'MAJOR_FACILITY_OUTAGE', simulated_downtime_hours NUMERIC(8,2) DEFAULT 120.0, simulated_impact_usd NUMERIC(14,2) DEFAULT 450000.00, status TEXT DEFAULT 'SIMULATED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_resilience (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, facility_id UUID, redundancy_level TEXT DEFAULT 'N_PLUS_ONE', recovery_time_hours NUMERIC(6,2) DEFAULT 12.0, resilience_score NUMERIC(5,2) DEFAULT 91.5, evaluated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_obsolescence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, asset_id UUID, obsolescence_risk TEXT DEFAULT 'LOW', manufacturer_support_status TEXT DEFAULT 'SUPPORTED', detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_recommendations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, recommendation_type TEXT NOT NULL, title TEXT NOT NULL, rationale TEXT NOT NULL, confidence_score NUMERIC(5,2) DEFAULT 89.0, status TEXT DEFAULT 'AI_PROPOSED', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_drift (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, entity_id UUID NOT NULL, drift_type TEXT NOT NULL, drift_level TEXT DEFAULT 'NO_DRIFT', detected_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS enterprise_asset_traces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID, root_signal_id TEXT NOT NULL, trace_payload JSONB DEFAULT '{}'::jsonb, provenance_hash TEXT NOT NULL, generated_at TIMESTAMPTZ DEFAULT NOW());
